import XCTest
@testable import LKSync

/// C02 – the merge port must reproduce web/js/sync.js exactly (vectors/sync.json is generated by running the REAL web code).
final class SyncVectorTests: XCTestCase {
    lazy var v: JSON = (try? Vectors.load("sync.json")) ?? .null
    var now: Double { JSON.num(v["now"]) }
    var nonCommutative: Set<String> { Set((v["nonCommutative"]?.array ?? []).compactMap(\.string)) }

    func merge(_ c: JSON) -> SyncDoc {
        SyncMerge.merge(local: SyncDoc(json: c["local"]!), remote: SyncDoc(json: c["remote"]!), now: now)
    }
    func keys(_ j: JSON) -> [String] { Array((j.object ?? [:]).keys) }

    /// merge(local, remote) == out for every case, field by field.
    func testParityC02() throws {
        let cases = v["merge"]?.array ?? []
        XCTAssertGreaterThanOrEqual(cases.count, 30, "sync.json merge cases")
        for c in cases {
            let name = c["name"]?.string ?? "?", out = c["out"]!
            let got = merge(c).vectorJSON(keys: keys(out))
            if let d = jsonDiff(got, out) { XCTFail("merge «\(name)»: \(d)") }
        }
    }

    /// merge(a, b) == merge(b, a) except where the web itself is not commutative (settings tie → local kept).
    func testMergeCommutative() {
        for c in v["merge"]?.array ?? [] {
            let name = c["name"]?.string ?? "?"
            guard !nonCommutative.contains(name) else { continue }
            let a = SyncDoc(json: c["local"]!), b = SyncDoc(json: c["remote"]!)
            let ab = SyncMerge.merge(local: a, remote: b, now: now).vectorJSON(), ba = SyncMerge.merge(local: b, remote: a, now: now).vectorJSON()
            if let d = jsonDiff(ab, ba) { XCTFail("not commutative «\(name)»: \(d)") }
        }
    }

    /// merge(merge(a, b), b) == merge(a, b) and merge(x, x) == x.
    func testMergeIdempotent() {
        for c in v["merge"]?.array ?? [] {
            let name = c["name"]?.string ?? "?"
            let b = SyncDoc(json: c["remote"]!)
            let once = merge(c)
            let twice = SyncMerge.merge(local: once, remote: b, now: now)
            if let d = jsonDiff(twice.vectorJSON(), once.vectorJSON()) { XCTFail("not idempotent «\(name)»: \(d)") }
            let self2 = SyncMerge.merge(local: once, remote: once, now: now)
            if let d = jsonDiff(self2.vectorJSON(), once.vectorJSON()) { XCTFail("merge(x,x) ≠ x «\(name)»: \(d)") }
        }
    }

    /// Cross-client scenarios (web, add-on, iOS, Android against one server Doc) replayed with the native merge:
    /// every client – and the server – must end exactly where the web reference ended.
    func testCrossClientScenarios() {
        let empty = SyncDoc(json: (v["merge"]?.array?.first?["local"])!)   // a fresh client = "both sides empty" local
        for sc in v["scenarios"]?.array ?? [] {
            let name = sc["name"]?.string ?? "?", expect = sc["expect"]?.object ?? [:]
            var lib = Set<String>()   // library words (web lexicon): the expected docs carry them as L:1 slim cards
            for d in expect.values { for (k, c) in d["cards"]?.object ?? [:] where JSON.num(c["L"]) == 1 { lib.insert(k) } }
            var clients: [String: SyncDoc] = [:], addon: SyncDoc?, server: SyncDoc?
            func make(_ key: String, _ at: Double) -> JSON {
                let parts = key.split(separator: ":", maxSplits: 1).map(String.init)
                let tl = parts.count == 2 ? parts[0] : nil, word = parts.count == 2 ? parts[1] : key
                let srs: JSON = ["ef": 2.5, "interval": 0, "reps": 0, "lapses": 0, "due": .number(at), "last": .null, "step": 0]
                if lib.contains(key) { return ["word": .string(word), "imageCredit": .null, "added": .number(at), "srs": srs, "L": 1] }
                var c: JSON = ["word": .string(word), "ipa": "", "pos": "", "vi": "", "def": "", "ex": "", "col": [], "syn": [], "level": "", "topic": "mine",
                               "emoji": "📘", "image": "", "imageCredit": .null, "audio": "", "sentences": [], "contexts": [], "note": "", "added": .number(at), "srs": srs]
                if let tl, tl != "en" { c["tl"] = .string(tl) }
                return SyncCodec.slim(c)
            }
            func edit(_ d: inout SyncDoc, _ st: JSON) {
                let key = st["card"]!.string!, at = JSON.num(st["at"])
                var c = JSON.spread(d.cards[key] ?? make(key, at))
                for (k, x) in st["patch"]?.object ?? [:] { c[k] = x }
                c["mod"] = .number(at)
                d.cards[key] = SyncCodec.slim(.object(c))
            }
            for st in sc["steps"]?.array ?? [] {
                let who = st["client"]!.string!, op = st["op"]!.string!, at = JSON.num(st["at"])
                if who == "addon" && op != "sync" {
                    var a = addon ?? SyncDoc(cards: [:], deleted: [:], stats: SyncDoc.emptyStats)
                    if op == "delete" { a.cards[st["card"]!.string!] = nil; a.deleted[st["card"]!.string!] = at } else { edit(&a, st) }
                    addon = a; continue
                }
                let cl = who == "addon" ? "web" : who
                var d = clients[cl] ?? empty
                switch op {
                case "edit", "offline_edit": edit(&d, st)
                case "delete": d.cards[st["card"]!.string!] = nil; d.deleted[st["card"]!.string!] = at
                case "sync":
                    var x = server.map { SyncMerge.merge(local: d, remote: $0, now: at) } ?? d
                    x.cards = x.cards.mapValues(SyncCodec.slim)
                    if cl == "web", let a = addon {   // web on the add-on's machine: bridge get → merge → set (sync.js syncExtension)
                        let del = SyncMerge.unionDeleted(x.deleted, a.deleted)
                        x.cards = SyncMerge.mergeCards(x.cards, a.cards, deleted: del).mapValues(SyncCodec.slim)
                        x.deleted = del
                        x.stats = SyncMerge.mergeStats(x.stats, a.stats ?? ["days": [:]])
                        addon = SyncDoc(cards: x.cards, deleted: del, stats: x.stats)
                    }
                    d = x; server = x
                default: XCTFail("unknown op \(op)")
                }
                clients[cl] = d
            }
            for (who, want) in expect {
                let got: SyncDoc? = who == "server" ? server : who == "addon" ? addon : clients[who]
                guard let got else { XCTFail("«\(name)» \(who): never ran"); continue }
                if let d = jsonDiff(got.vectorJSON(keys: keys(want)), want) { XCTFail("scenario «\(name)» \(who): \(d)") }
            }
        }
    }

    // MARK: codec (values from the JS functions in web/js/sync.js)
    func testBucketAndHashMatchWeb() {
        let cases: [(String, Int, String)] = [("curriculum", 26, "-984572869:10"), ("naïve", 12, "104710475:5"), ("ja:食べる", 11, "-1130962034:6"),
                                              ("constructor", 15, "-1588406278:11"), ("🍣", 8, "1773223:2"), ("don't", 13, "95765936:5")]
        for (w, b, h) in cases {
            XCTAssertEqual(SyncCodec.bucketOf(w), b, w)
            XCTAssertEqual(SyncCodec.hash(w), h, w)
        }
    }

    func testStableStringMatchesJS() throws {
        let j: JSON = ["b": 1, "a": ["d": 2, "c": "\n\u{01}é"], "10": 1, "9": 2, "x": [3, ["z": 1, "y": 2]]]
        XCTAssertEqual(j.stableString, #"{"9":2,"10":1,"a":{"c":"\n\u0001é","d":2},"b":1,"x":[3,{"y":2,"z":1}]}"#)
        XCTAssertEqual([0.1, 1e21, 1e-7, 123456789012345680000, -0.0, 5e-324, 1.5, 100, 0.000001, 9007199254740992].map(JSON.jsNumberString),
                       ["0.1", "1e+21", "1e-7", "123456789012345680000", "0", "5e-324", "1.5", "100", "0.000001", "9007199254740992"])
    }

    func testGzipInteropWithWeb() throws {
        // produced by Node zlib.gzipSync (same format as CompressionStream('gzip'))
        let web = "H4sIAAAAAAAAE6tWykjNyclXslIqyXi4a79CeubD3bMzlWoBsviJIxgAAAA="
        XCTAssertEqual(try SyncCodec.docText(["z": .string(web)]), #"{"hello":"thế giới"}"#)
        let long = String(repeating: #"{"word":"curriculum","srs":{"due":1772366400000}},"#, count: 40)
        let body = SyncCodec.docBody(long)
        XCTAssertNotNil(body["z"], "long text is compressed")
        XCTAssertEqual(try SyncCodec.docText(body), long)
        XCTAssertEqual(try SyncCodec.docText(SyncCodec.docBody("{}")), "{}")
        XCTAssertThrowsError(try SyncCodec.gunzip(Data([0x1F, 0x8B, 0x08, 0, 1, 2, 3])))
    }

    func testDriveEnvelopeRoundTripAndRejects() throws {
        let snap = SyncEngine.snapshotJSON(SyncDoc(cards: ["a": ["word": "a", "added": 1]], stats: SyncDoc.emptyStats), now: 1)
        XCTAssertEqual(try SyncCodec.driveUnpack(SyncCodec.drivePack(snap)), snap)
        // tampered data → sha mismatch → corrupt (never merged)
        var env = try JSON.parse(SyncCodec.gunzip(SyncCodec.drivePack(snap)))
        env["data"] = .string(#"{"cards":{}}"#)
        XCTAssertThrowsError(try SyncCodec.driveUnpack(env.data)) { XCTAssertEqual($0 as? SyncCodec.CodecError, .sha) }
        env["v"] = 3
        XCTAssertThrowsError(try SyncCodec.driveUnpack(env.data)) { XCTAssertEqual($0 as? SyncCodec.CodecError, .newer(3)) }
    }

    func testPushPayloadShape() throws {
        var doc = SyncDoc(cards: [:], stats: SyncDoc.emptyStats, game: ["xp": 5, "questsDone": ["q": 1]], settings: ["dailyGoal": 30], settingsAt: 7)
        for i in 0..<100 { doc.cards["w\(i)"] = ["word": .string("w\(i)"), "added": .number(Double(i)), "contexts": [], "sentences": []] }
        let (docs, pending, hs) = SyncEngine.buildPush(doc, sent: [:], now: 1_000)
        XCTAssertEqual(hs.count, 32)
        XCTAssertNotNil(docs["meta"])
        let meta = try JSON.parse(docs["meta"]!["body"]!.string!)
        XCTAssertEqual(meta["chunks"], 32)
        let mt = try JSON.parse(SyncCodec.docText(meta))
        XCTAssertEqual(mt["game"]?["questsDone"], [:], "questsDone is per device")
        XCTAssertEqual(mt["settingsAt"], 7)
        var all: [String: JSON] = [:]
        for (k, d) in docs where k != "meta" {
            let txt = try SyncCodec.docText(try JSON.parse(d["body"]!.string!))
            XCTAssertEqual(SyncCodec.hash(txt), d["h"]?.string)
            for (w, c) in try JSON.parse(txt).object ?? [:] { XCTAssertEqual(SyncCodec.bucketOf(w), Int(k.dropFirst(6))); all[w] = c }
        }
        XCTAssertEqual(all.count, 100)
        XCTAssertNil(all["w1"]?["contexts"], "slim() drops empty contexts")
        // nothing changed → nothing sent
        let again = SyncEngine.buildPush(doc, sent: pending, now: 1_000)
        XCTAssertTrue(again.docs.isEmpty)
    }
}
